/* From Uiverse.io by boryanakrasteva - Tags: card */
.__UIV_SCOPE__ .card {
  width: 300px;
  height: 254px;
  background: lightgrey;
  overflow: hidden;
  display: flex;
}

.__UIV_SCOPE__ .circles,
.__UIV_SCOPE__ .browser {
  height: 30px;
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .circles {
  width: 20%;
  gap: 8px;
  padding: 10px;
}

.__UIV_SCOPE__ .c {
  width: 09px;
  height: 9px;
  border-radius: 50%;
  box-shadow: inset 2px 2px 5px rgba(235, 235, 235, 0.356);
}

.__UIV_SCOPE__ .c:first-child {
  background-color: red;
}

.__UIV_SCOPE__ .c:nth-child(2) {
  background-color: rgb(204, 167, 4);
}

.__UIV_SCOPE__ .c:last-child {
  background-color: green;
}

.__UIV_SCOPE__ .browser {
  width: 80%;
  padding: 5px;
  display: flex;
  gap: 10px;
}

.__UIV_SCOPE__ .chevrons {
  display: flex;
}

.__UIV_SCOPE__ .search-bar {
  position: relative;
  border: 0.5px solid black;
  border-radius: 5px;
  padding: 5px;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  color: rgb(88, 88, 88);
  box-shadow: inset 2px 2px 2px #05050525;
}

.__UIV_SCOPE__ .search-bar svg {
  position: absolute;
  left: 10px;
}
